function escapeHtml(v){return String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}
function normalize(v){return String(v??"").trim().toLowerCase()}function findStudent(id){return teacherCoopState.students.find(s=>s.id===id)}
function formatThaiDate(v){if(!v)return"-";const d=new Date(`${v}T00:00:00`);return Number.isNaN(d.getTime())?v:d.toLocaleDateString("th-TH",{day:"numeric",month:"short",year:"numeric"})}
function statusHtml(status){const c=TC_REQUEST_STATUS[status]||{label:status,cls:"tc-status-muted"};return `<span class="tc-status ${c.cls}">${escapeHtml(c.label)}</span>`}
function careStatusHtml(s){if(s.careOwner==="me")return'<span class="tc-status tc-status-success">ฉันกำลังดูแล</span>';if(s.careOwner==="other")return'<span class="tc-status tc-status-muted">มีอาจารย์ดูแลแล้ว</span>';return'<span class="tc-status tc-status-warning">ยังไม่ได้รับดูแล</span>'}
function roleText(s){const r=[];if(s.roles.supervisor)r.push("อาจารย์นิเทศ");if(s.roles.advisor)r.push("ที่ปรึกษาโครงการ");return r.length?r.join(" + "):"-"}
function saveTeacherMockState(){localStorage.setItem("teacherCoopRedesignState",JSON.stringify({profile:teacherCoopState.profile,students:teacherCoopState.students}))}
function loadTeacherMockState(){try{const s=JSON.parse(localStorage.getItem("teacherCoopRedesignState")||"null");if(!s)return;if(s.profile)teacherCoopState.profile={...teacherCoopState.profile,...s.profile};if(Array.isArray(s.students))teacherCoopState.students=s.students}catch(e){console.warn(e)}}
function setCellLabels(sel){document.querySelectorAll(sel).forEach(t=>{const h=[...t.querySelectorAll("thead th")].map(x=>x.textContent.trim());t.querySelectorAll("tbody tr").forEach(r=>[...r.children].forEach((c,i)=>c.dataset.label=h[i]||""))})}function refreshResponsiveTableLabels(){setCellLabels(".tc-table")}

function switchTeacherPanel(id){teacherCoopState.activePanel=id;document.querySelectorAll(".tc-panel").forEach(p=>p.classList.toggle("active",p.id===id));document.querySelectorAll(".tc-sidebar-item[data-panel]").forEach(b=>b.classList.toggle("active",b.dataset.panel===id));window.scrollTo({top:0,behavior:"smooth"})}
function switchStudentTab(n){teacherCoopState.activeStudentTab=n;document.querySelectorAll("[data-student-tab]").forEach(b=>b.classList.toggle("active",b.dataset.studentTab===n));document.querySelectorAll("[data-student-tab-panel]").forEach(p=>p.classList.toggle("active",p.dataset.studentTabPanel===n));if(n==="search")renderStudentSearch();if(n==="managed")renderManagedStudents();if(n==="confirm")renderStudentConfirmations()}
function switchSupervisionTab(n){teacherCoopState.activeSupervisionTab=n;document.querySelectorAll("[data-supervision-tab]").forEach(b=>b.classList.toggle("active",b.dataset.supervisionTab===n));document.querySelectorAll("[data-supervision-tab-panel]").forEach(p=>p.classList.toggle("active",p.dataset.supervisionTabPanel===n));renderSupervision()}
function switchEvaluationTab(n){teacherCoopState.activeEvaluationTab=n;document.querySelectorAll("[data-evaluation-tab]").forEach(b=>b.classList.toggle("active",b.dataset.evaluationTab===n));document.querySelectorAll("[data-evaluation-tab-panel]").forEach(p=>p.classList.toggle("active",p.dataset.evaluationTabPanel===n));renderEvaluations()}

function getManagedStudents(){return teacherCoopState.students.filter(s=>s.careOwner==="me")}function getPendingConfirmations(){return getManagedStudents().filter(s=>s.roles.advisor&&!s.advisorConfirmed)}
function isUpcomingVisit(r){if(!r?.appointmentSaved||!r.date||r.resultStatus==="complete")return false;return new Date(`${r.date}T${r.time||"00:00"}`).getTime()>=Date.now()-86400000}
function countUpcomingVisits(){return getManagedStudents().reduce((c,s)=>c+[1,2].filter(n=>isUpcomingVisit(s.supervision[n])).length,0)}
function countPendingEvaluations(){return getManagedStudents().reduce((c,s)=>{let t=0;if(s.evaluations.student.status!=="complete")t++;if(s.evaluations.company.status!=="complete")t++;if(s.evaluations.visit2.status!=="complete")t++;FINAL_WORK_TYPES.forEach(({key})=>{if(s.evaluations.final[key].score===null)t++});return c+t},0)}
function countSupervisionTasks(){return getManagedStudents().filter(s=>s.roles.supervisor).reduce((c,s)=>{let t=0;[1,2].forEach(n=>{const r=s.supervision[n];if(!r.appointmentSaved)t++;if(!s.mentor.confirmed&&!s.mentor.representative)t++;if(r.resultStatus!=="complete")t++;if(!r.photos[0]||!r.photos[1])t++;if(!r.pdfGenerated)t++});return c+t},0)}
function updateOverview(){const m=getManagedStudents(),pr=teacherCoopState.students.filter(s=>s.requestStatus==="pending").length,pc=getPendingConfirmations().length,uv=countUpcomingVisits(),pe=countPendingEvaluations(),st=countSupervisionTasks();statManagedStudents.textContent=m.length;statPendingRequests.textContent=pr;statPendingConfirmations.textContent=pc;statUpcomingVisits.textContent=uv;statPendingEvaluations.textContent=pe;managedStudentTabCount.textContent=m.length;confirmationTabCount.textContent=pc;studentPendingBadge.textContent=pc;requestPendingBadge.textContent=pr;supervisionTaskBadge.textContent=st;evaluationTaskBadge.textContent=pe;[[studentPendingBadge,pc],[requestPendingBadge,pr],[supervisionTaskBadge,st],[evaluationTaskBadge,pe]].forEach(([el,v])=>el.style.display=v>0?"inline-flex":"none");renderOverviewTasks({pr,pc,uv,pe})}
function renderOverviewTasks({pr,pc,uv,pe}){const tasks=[{v:pr>0,i:"fa-file-signature",tone:"warning",title:`คำร้องรอพิจารณา ${pr} รายการ`,text:"ตรวจสอบรายละเอียดและบันทึกผลคำร้อง",a:"goToRequestPanel()",b:"ตรวจสอบ"},{v:pc>0,i:"fa-user-check",tone:"danger",title:`ข้อมูลนักศึกษารอยืนยัน ${pc} รายการ`,text:"ยืนยันข้อมูลนักศึกษาที่เป็นที่ปรึกษาโครงการ",a:"goToStudentConfirmations()",b:"ยืนยันข้อมูล"},{v:uv>0,i:"fa-calendar-days",tone:"primary",title:`นัดนิเทศที่กำลังจะถึง ${uv} นัด`,text:"ตรวจสอบวันนัดหมายและข้อมูลพี่เลี้ยง",a:"goToSupervisionPanel()",b:"จัดการ"},{v:pe>0,i:"fa-star-half-stroke",tone:"purple",title:`งานประเมินค้าง ${pe} รายการ`,text:"ประเมินนักศึกษา สถานประกอบการ และผลงาน",a:"goToEvaluationPanel()",b:"ประเมิน"}].filter(x=>x.v);overviewTaskList.innerHTML=tasks.length?tasks.map(t=>`<div class="tc-task-row"><div class="icon ${t.tone}"><i class="fa-solid ${t.i}"></i></div><div><strong>${escapeHtml(t.title)}</strong><span>${escapeHtml(t.text)}</span></div><button class="tc-btn tc-btn-outline tc-btn-sm" type="button" onclick="${t.a}">${escapeHtml(t.b)}</button></div>`).join(""):`<div class="tc-info-banner"><i class="fa-solid fa-circle-check"></i><span>ไม่มีงานค้างในขณะนี้</span></div>`}
function goToRequestPanel(){switchTeacherPanel("panel-requests")}function goToStudentConfirmations(){switchTeacherPanel("panel-students");switchStudentTab("confirm")}function goToSupervisionPanel(){switchTeacherPanel("panel-supervision");switchSupervisionTab("overview")}function goToEvaluationPanel(){switchTeacherPanel("panel-evaluation")}

function getFilteredStudentSearch(){const k=normalize(studentSearchInput.value),m=studentMajorFilter.value,c=studentCareFilter.value;return teacherCoopState.students.filter(s=>(!k||normalize(`${s.name} ${s.id} ${s.company} ${s.position}`).includes(k))&&(!m||s.major===m)&&(!c||s.careOwner===c))}
function renderStudentSearch(){const a=getFilteredStudentSearch();studentSearchEmpty.classList.toggle("show",!a.length);studentSearchTableBody.innerHTML=a.map(s=>{const action=s.requestStatus==="approved"&&s.careOwner==="available"?`<button class="tc-btn tc-btn-primary tc-btn-sm" type="button" onclick="openSelectStudentModal('${escapeHtml(s.id)}')"><i class="fa-solid fa-user-plus"></i>เลือกดูแล</button>`:`<button class="tc-btn tc-btn-outline tc-btn-sm" type="button" onclick="openStudentDetail('${escapeHtml(s.id)}')"><i class="fa-solid fa-eye"></i>ดูข้อมูล</button>`;return`<tr><td><span class="tc-table-primary">${escapeHtml(s.name)}</span><span class="tc-table-secondary">${escapeHtml(s.id)}</span></td><td>${escapeHtml(s.major)}</td><td><span class="tc-table-primary">${escapeHtml(s.company)}</span><span class="tc-table-secondary">${escapeHtml(s.position)}</span></td><td>${careStatusHtml(s)}<span class="tc-table-secondary">${escapeHtml(TC_REQUEST_STATUS[s.requestStatus]?.label||"")}</span></td><td><div class="tc-table-actions">${action}</div></td></tr>`}).join("");refreshResponsiveTableLabels()}
function openSelectStudentModal(id){const s=findStudent(id);if(!s)return;teacherCoopState.selectingStudentId=id;selectStudentPreview.innerHTML=`<strong>${escapeHtml(s.name)}</strong><span>${escapeHtml(s.id)} • ${escapeHtml(s.major)} • ${escapeHtml(s.company)}</span>`;roleSupervisor.checked=false;roleAdvisor.checked=false;openModal("selectStudentModal")}
async function confirmStudentSelection(){const s=findStudent(teacherCoopState.selectingStudentId);if(!s)return;const sup=roleSupervisor.checked,adv=roleAdvisor.checked;if(!sup&&!adv){showToast({type:"warning",title:"กรุณาเลือกอย่างน้อย 1 บทบาท",message:"เลือกอาจารย์นิเทศ หรืออาจารย์ที่ปรึกษาโครงการ"});return}const roles=[];if(sup)roles.push("อาจารย์นิเทศ");if(adv)roles.push("อาจารย์ที่ปรึกษาโครงการ");if(!await showConfirm({title:"ยืนยันการรับนักศึกษาเข้าดูแล",message:`${s.name}\nบทบาท: ${roles.join(" + ")}`,confirmText:"ยืนยัน"}))return;s.careOwner="me";s.roles.supervisor=sup;s.roles.advisor=adv;s.advisorConfirmed=!adv;teacherCoopState.selectingStudentId=null;closeModal("selectStudentModal");commitAll();showToast({type:"success",title:"รับนักศึกษาเข้าดูแลแล้ว",message:`${s.name} • ${roles.join(" + ")}`})}
function calculateStudentProgress(s){if(s.careOwner!=="me")return 0;let p=1,total=6;if(!s.roles.advisor||s.advisorConfirmed)p++;if(s.supervision[1].resultStatus==="complete")p++;if(s.supervision[2].resultStatus==="complete")p++;if(s.evaluations.student.status==="complete"&&s.evaluations.company.status==="complete"&&s.evaluations.visit2.status==="complete")p++;if(FINAL_WORK_TYPES.every(({key})=>s.evaluations.final[key].score!==null))p++;return Math.round(p/total*100)}
function renderManagedStudents(){const a=getManagedStudents();managedStudentEmpty.classList.toggle("show",!a.length);managedStudentTableBody.innerHTML=a.map(s=>{const p=calculateStudentProgress(s);return`<tr><td><span class="tc-table-primary">${escapeHtml(s.name)}</span><span class="tc-table-secondary">${escapeHtml(s.id)} • ${escapeHtml(s.major)}</span></td><td><span class="tc-status tc-status-primary">${escapeHtml(roleText(s))}</span></td><td><span class="tc-table-primary">${escapeHtml(s.company)}</span><span class="tc-table-secondary">${escapeHtml(s.position)}</span></td><td><div class="tc-progress"><div class="tc-progress-bar"><span style="width:${p}%"></span></div><small>${p}% ของ Workflow</small></div></td><td><button class="tc-btn tc-btn-outline tc-btn-sm" type="button" onclick="openStudentDetail('${escapeHtml(s.id)}')"><i class="fa-solid fa-eye"></i>ดูข้อมูล</button></td></tr>`}).join("");refreshResponsiveTableLabels()}
function renderStudentConfirmations(){const a=getPendingConfirmations();studentConfirmationEmpty.classList.toggle("show",!a.length);studentConfirmationList.innerHTML=a.map(s=>`<div class="tc-confirmation-card"><div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.id)} • ${escapeHtml(s.company)}</p><div class="tc-confirmation-meta"><span><i class="fa-solid fa-graduation-cap"></i> ${escapeHtml(s.major)}</span><span><i class="fa-solid fa-lightbulb"></i> ${escapeHtml(s.projectTitle)}</span></div></div><div class="tc-table-actions"><button class="tc-btn tc-btn-outline tc-btn-sm" type="button" onclick="openStudentDetail('${escapeHtml(s.id)}',true)"><i class="fa-solid fa-eye"></i>ตรวจสอบ</button><button class="tc-btn tc-btn-primary tc-btn-sm" type="button" onclick="confirmAdvisorStudent('${escapeHtml(s.id)}')"><i class="fa-solid fa-circle-check"></i>ยืนยันข้อมูล</button></div></div>`).join("")}
function openStudentDetail(id,mode=false){const s=findStudent(id);if(!s)return;studentDetailModalBody.innerHTML=`<div class="tc-detail-grid"><div class="tc-detail-card"><span>ชื่อ-นามสกุล</span><strong>${escapeHtml(s.name)}</strong></div><div class="tc-detail-card"><span>รหัสนักศึกษา</span><strong>${escapeHtml(s.id)}</strong></div><div class="tc-detail-card"><span>สาขา</span><strong>${escapeHtml(s.major)}</strong></div><div class="tc-detail-card"><span>บทบาทของฉัน</span><strong>${escapeHtml(roleText(s))}</strong></div><div class="tc-detail-card full"><span>สถานประกอบการ</span><strong>${escapeHtml(s.company)}</strong></div><div class="tc-detail-card"><span>ตำแหน่ง</span><strong>${escapeHtml(s.position)}</strong></div><div class="tc-detail-card"><span>จังหวัด</span><strong>${escapeHtml(s.province)}</strong></div><div class="tc-detail-card full"><span>หัวข้อโครงการ</span><strong>${escapeHtml(s.projectTitle)}</strong></div><div class="tc-detail-card full"><span>ระยะเวลาสหกิจ</span><strong>${escapeHtml(s.duration)}</strong></div></div>`;studentDetailModalFooter.innerHTML=mode&&s.roles.advisor&&!s.advisorConfirmed?`<button class="tc-btn tc-btn-outline" type="button" onclick="closeModal('studentDetailModal')">ปิด</button><button class="tc-btn tc-btn-primary" type="button" onclick="closeModal('studentDetailModal');confirmAdvisorStudent('${escapeHtml(s.id)}')"><i class="fa-solid fa-circle-check"></i>ยืนยันข้อมูล</button>`:`<button class="tc-btn tc-btn-outline" type="button" onclick="closeModal('studentDetailModal')">ปิด</button>`;openModal("studentDetailModal")}
async function confirmAdvisorStudent(id){const s=findStudent(id);if(!s||!s.roles.advisor)return;if(!await showConfirm({title:"ยืนยันข้อมูลนักศึกษาที่ปรึกษาโครงการ",message:`${s.name}\nหัวข้อโครงการ: ${s.projectTitle}`,confirmText:"ยืนยันข้อมูล"}))return;s.advisorConfirmed=true;commitAll();showToast({type:"success",title:"ยืนยันข้อมูลแล้ว",message:s.name})}

function renderRequestCounts(){const all=teacherCoopState.students.length,p=teacherCoopState.students.filter(s=>s.requestStatus==="pending").length,a=teacherCoopState.students.filter(s=>s.requestStatus==="approved").length,r=teacherCoopState.students.filter(s=>s.requestStatus==="rejected").length;requestAllCount.textContent=all;requestPendingCount.textContent=p;requestApprovedCount.textContent=a;requestRejectedCount.textContent=r}
function getFilteredRequests(){const k=normalize(requestSearchInput.value),m=requestMajorFilter.value,st=teacherCoopState.activeRequestFilter;return teacherCoopState.students.filter(s=>(!k||normalize(`${s.name} ${s.id} ${s.company} ${s.position}`).includes(k))&&(!m||s.major===m)&&(!st||s.requestStatus===st))}
function renderRequests(){renderRequestCounts();const a=getFilteredRequests();requestEmpty.classList.toggle("show",!a.length);requestTableBody.innerHTML=a.map(s=>`<tr><td><span class="tc-table-primary">${escapeHtml(s.name)}</span><span class="tc-table-secondary">${escapeHtml(s.id)} • ${escapeHtml(s.major)}</span></td><td><span class="tc-table-primary">${escapeHtml(s.company)}</span><span class="tc-table-secondary">${escapeHtml(s.position)}</span></td><td>${escapeHtml(s.submittedDate)}</td><td>${statusHtml(s.requestStatus)}</td><td><button class="tc-btn tc-btn-outline tc-btn-sm" type="button" onclick="openRequestDetail('${escapeHtml(s.id)}')"><i class="fa-solid fa-eye"></i>ตรวจสอบ</button></td></tr>`).join("");refreshResponsiveTableLabels()}
function setRequestFilter(st){teacherCoopState.activeRequestFilter=st;document.querySelectorAll("[data-request-filter]").forEach(b=>b.classList.toggle("active",b.dataset.requestFilter===st));renderRequests()}
function openRequestDetail(id){const s=findStudent(id);if(!s)return;teacherCoopState.requestActionStudentId=id;requestDetailBody.innerHTML=`<div class="tc-detail-grid"><div class="tc-detail-card"><span>ชื่อ-นามสกุล</span><strong>${escapeHtml(s.name)}</strong></div><div class="tc-detail-card"><span>รหัสนักศึกษา</span><strong>${escapeHtml(s.id)}</strong></div><div class="tc-detail-card"><span>สาขา</span><strong>${escapeHtml(s.major)}</strong></div><div class="tc-detail-card"><span>วันที่ยื่น</span><strong>${escapeHtml(s.submittedDate)}</strong></div><div class="tc-detail-card full"><span>สถานประกอบการ</span><strong>${escapeHtml(s.company)}</strong></div><div class="tc-detail-card"><span>ตำแหน่ง</span><strong>${escapeHtml(s.position)}</strong></div><div class="tc-detail-card"><span>จังหวัด</span><strong>${escapeHtml(s.province)}</strong></div><div class="tc-detail-card full"><span>ระยะเวลาสหกิจ</span><strong>${escapeHtml(s.duration)}</strong></div><div class="tc-detail-card full"><span>สถานะคำร้อง</span>${statusHtml(s.requestStatus)}</div>${s.requestStatus==="rejected"&&s.rejectReason?`<div class="tc-detail-card full"><span>เหตุผลที่ไม่อนุมัติ</span><strong>${escapeHtml(s.rejectReason)}</strong></div>`:""}</div>`;requestDetailFooter.innerHTML=s.requestStatus==="pending"?`<button class="tc-btn tc-btn-outline" type="button" onclick="closeModal('requestDetailModal')">ปิด</button><button class="tc-btn tc-btn-danger" type="button" onclick="closeModal('requestDetailModal');openRejectRequest('${escapeHtml(s.id)}')"><i class="fa-solid fa-circle-xmark"></i>ไม่อนุมัติ</button><button class="tc-btn tc-btn-primary" type="button" onclick="closeModal('requestDetailModal');approveRequest('${escapeHtml(s.id)}')"><i class="fa-solid fa-circle-check"></i>อนุมัติ</button>`:`<button class="tc-btn tc-btn-outline" type="button" onclick="closeModal('requestDetailModal')">ปิด</button>`;openModal("requestDetailModal")}
async function approveRequest(id){const s=findStudent(id);if(!s||s.requestStatus!=="pending")return;if(!await showConfirm({title:"อนุมัติคำร้องสหกิจศึกษา",message:`ยืนยันการอนุมัติคำร้องของ ${s.name} หรือไม่?`,confirmText:"อนุมัติ"}))return;s.requestStatus="approved";s.rejectReason="";commitAll();showToast({type:"success",title:"อนุมัติคำร้องเรียบร้อยแล้ว",message:s.name})}
function openRejectRequest(id){const s=findStudent(id);if(!s||s.requestStatus!=="pending")return;teacherCoopState.requestActionStudentId=id;rejectRequestPreview.innerHTML=`<strong>${escapeHtml(s.name)}</strong><span>${escapeHtml(s.id)} • ${escapeHtml(s.company)}</span>`;rejectRequestReason.value="";openModal("rejectRequestModal")}
function submitRejectRequest(){const s=findStudent(teacherCoopState.requestActionStudentId),reason=rejectRequestReason.value.trim();if(!s)return;if(!reason){showToast({type:"warning",title:"กรุณาระบุเหตุผล",message:"ต้องระบุเหตุผลก่อนยืนยันไม่อนุมัติคำร้อง"});return}s.requestStatus="rejected";s.rejectReason=reason;closeModal("rejectRequestModal");commitAll();showToast({type:"success",title:"บันทึกผลคำร้องแล้ว",message:`ไม่อนุมัติคำร้องของ ${s.name}`})}

function getSupervisionStudents(){return getManagedStudents().filter(s=>s.roles.supervisor)}function getRoundStatusText(s,n){const r=s.supervision[n];if(r.resultStatus==="complete"&&r.pdfGenerated)return{label:"เสร็จสิ้น",cls:"tc-status-success"};if(r.resultStatus==="complete")return{label:"รอสร้าง PDF",cls:"tc-status-warning"};if(r.appointmentSaved)return{label:`นัดแล้ว ${formatThaiDate(r.date)}`,cls:"tc-status-primary"};return{label:"ยังไม่กำหนด",cls:"tc-status-muted"}}
function renderSupervisionOverview(){const k=normalize(supervisionSearchInput.value),f=supervisionStatusFilter.value;let a=getSupervisionStudents().filter(s=>{const complete=s.supervision[1].resultStatus==="complete"&&s.supervision[1].pdfGenerated&&s.supervision[2].resultStatus==="complete"&&s.supervision[2].pdfGenerated;return(!k||normalize(`${s.name} ${s.company}`).includes(k))&&(!f||(f==="complete"&&complete)||(f==="pending"&&!complete))});supervisionOverviewEmpty.classList.toggle("show",!a.length);supervisionOverviewBody.innerHTML=a.map(s=>{const r1=getRoundStatusText(s,1),r2=getRoundStatusText(s,2),ms=s.mentor.confirmed||s.mentor.representative?'<span class="tc-status tc-status-success">พร้อมนิเทศ</span>':'<span class="tc-status tc-status-warning">รอยืนยัน</span>';return`<tr><td><span class="tc-table-primary">${escapeHtml(s.name)}</span><span class="tc-table-secondary">${escapeHtml(s.id)} • ${escapeHtml(s.company)}</span></td><td><span class="tc-status ${r1.cls}">${escapeHtml(r1.label)}</span></td><td><span class="tc-status ${r2.cls}">${escapeHtml(r2.label)}</span></td><td>${ms}<span class="tc-table-secondary">${escapeHtml(s.mentor.representative?.name||s.mentor.name)}</span></td><td><div class="tc-table-actions"><button class="tc-btn tc-btn-outline tc-btn-sm" type="button" onclick="openSupervision('${escapeHtml(s.id)}',1)">ครั้งที่ 1</button><button class="tc-btn tc-btn-primary tc-btn-sm" type="button" onclick="openSupervision('${escapeHtml(s.id)}',2)">ครั้งที่ 2</button></div></td></tr>`}).join("");refreshResponsiveTableLabels()}
function renderSupervisionRoundCards(n){const w=document.getElementById(n===1?"supervisionWorkspaceRound1":"supervisionWorkspaceRound2"),a=getSupervisionStudents();w.innerHTML=a.length?a.map(s=>{const r=s.supervision[n],st=getRoundStatusText(s,n);return`<div class="tc-round-card"><div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.id)} • ${escapeHtml(s.company)}</p><div class="tc-round-card-meta"><span><i class="fa-solid fa-calendar"></i> ${r.appointmentSaved?`${formatThaiDate(r.date)} ${escapeHtml(r.time)}`:"ยังไม่นัดหมาย"}</span><span><i class="fa-solid fa-user-tie"></i> ${escapeHtml(s.mentor.representative?.name||s.mentor.name)}</span><span class="tc-status ${st.cls}">${escapeHtml(st.label)}</span></div></div><div class="tc-round-card-actions"><button class="tc-btn tc-btn-primary tc-btn-sm" type="button" onclick="openSupervision('${escapeHtml(s.id)}',${n})"><i class="fa-solid fa-pen-to-square"></i>จัดการนิเทศ</button></div></div>`}).join(""):`<div class="tc-empty show"><i class="fa-solid fa-calendar-xmark"></i><strong>ยังไม่มีนักศึกษาสำหรับนิเทศ</strong><span>ต้องรับนักศึกษาในบทบาทอาจารย์นิเทศก่อน</span></div>`}
function renderSupervision(){renderSupervisionOverview();renderSupervisionRoundCards(1);renderSupervisionRoundCards(2)}
function openSupervision(id,n){const s=findStudent(id);if(!s||s.careOwner!=="me"||!s.roles.supervisor)return;teacherCoopState.currentSupervision={studentId:id,round:Number(n),step:"appointment"};const r=s.supervision[n];supervisionModalTitle.textContent=`นิเทศครั้งที่ ${n}`;supervisionStudentPreview.innerHTML=`<div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.id)} • ${escapeHtml(s.company)} • ${escapeHtml(s.position)}</p></div><span class="tc-status tc-status-primary">นิเทศครั้งที่ ${n}</span>`;supervisionDate.value=r.date||"";supervisionTime.value=r.time||"";supervisionMode.value=r.mode||"onsite";supervisionPlace.value=r.place||"";supervisionAppointmentNote.value=r.appointmentNote||"";supervisionSummary.value=r.summary||"";supervisionSuggestion.value=r.suggestion||"";supervisionProblem.value=r.problem||"";mentorRepresentativeForm.classList.remove("show");renderMentorInformation();renderPhotoPreviews();renderPdfReadiness();switchSupervisionStep("appointment");openModal("supervisionModal")}
function switchSupervisionStep(n){teacherCoopState.currentSupervision.step=n;document.querySelectorAll("[data-supervision-step]").forEach(b=>b.classList.toggle("active",b.dataset.supervisionStep===n));document.querySelectorAll("[data-supervision-step-panel]").forEach(p=>p.classList.toggle("active",p.dataset.supervisionStepPanel===n));updateSupervisionStepperStatus()}
function getCurrentSupervisionContext(){const s=findStudent(teacherCoopState.currentSupervision.studentId);if(!s)return null;const n=teacherCoopState.currentSupervision.round;return{student:s,round:s.supervision[n],roundNo:n}}
function saveSupervisionAppointment(){const c=getCurrentSupervisionContext();if(!c)return;const d=supervisionDate.value,t=supervisionTime.value;if(!d||!t){showToast({type:"warning",title:"กรอกวันนัดหมายไม่ครบ",message:"กรุณาระบุวันที่และเวลานิเทศ"});return}Object.assign(c.round,{date:d,time:t,mode:supervisionMode.value,place:supervisionPlace.value.trim(),appointmentNote:supervisionAppointmentNote.value.trim(),appointmentSaved:true});commitAll(false);updateSupervisionStepperStatus();showToast({type:"success",title:"บันทึกนัดหมายแล้ว",message:`${c.student.name} • นิเทศครั้งที่ ${c.roundNo}`})}
function renderMentorInformation(){const c=getCurrentSupervisionContext();if(!c)return;const m=c.student.mentor,a=m.representative||m;mentorInformationBox.innerHTML=`<div class="tc-mentor-card"><div class="tc-mentor-item"><span>พี่เลี้ยงหลัก</span><strong>${escapeHtml(m.name)}</strong></div><div class="tc-mentor-item"><span>ตำแหน่ง</span><strong>${escapeHtml(m.position)}</strong></div><div class="tc-mentor-item"><span>อีเมล</span><strong>${escapeHtml(m.email)}</strong></div><div class="tc-mentor-item"><span>เบอร์โทรศัพท์</span><strong>${escapeHtml(m.phone)}</strong></div><div class="tc-mentor-item"><span>สถานะยืนยัน</span><strong>${m.confirmed?'<span class="tc-status tc-status-success">ยืนยันแล้ว</span>':'<span class="tc-status tc-status-warning">รอยืนยัน</span>'}</strong></div><div class="tc-mentor-item"><span>ผู้เข้าร่วมนิเทศ</span><strong>${escapeHtml(a.name)}${m.representative?" (ผู้แทน)":""}</strong></div></div>${m.representative?`<div class="tc-info-banner" style="margin-top:12px;margin-bottom:0"><i class="fa-solid fa-user-group"></i><span>ผู้แทนพี่เลี้ยง: ${escapeHtml(m.representative.name)} • ${escapeHtml(m.representative.position)} • เหตุผล: ${escapeHtml(m.representative.reason)}</span></div>`:""}`}
async function confirmMentorInformation(){const c=getCurrentSupervisionContext();if(!c)return;if(!await showConfirm({title:"ยืนยันข้อมูลพี่เลี้ยง",message:`ยืนยันข้อมูลพี่เลี้ยงของ ${c.student.name} สำหรับการนิเทศครั้งที่ ${c.roundNo} หรือไม่?`,confirmText:"ยืนยัน"}))return;c.student.mentor.confirmed=true;c.round.mentorConfirmed=true;commitAll(false);renderMentorInformation();updateSupervisionStepperStatus();showToast({type:"success",title:"ยืนยันข้อมูลพี่เลี้ยงแล้ว",message:c.student.mentor.name})}
function openMentorRepresentativeForm(){const c=getCurrentSupervisionContext();if(!c)return;const r=c.student.mentor.representative;representativeName.value=r?.name||"";representativePosition.value=r?.position||"";representativeEmail.value=r?.email||"";representativePhone.value=r?.phone||"";representativeReason.value=r?.reason||"";mentorRepresentativeForm.classList.add("show")}
function closeMentorRepresentativeForm(){mentorRepresentativeForm.classList.remove("show")}
function saveMentorRepresentative(){const c=getCurrentSupervisionContext();if(!c)return;const name=representativeName.value.trim(),position=representativePosition.value.trim(),email=representativeEmail.value.trim(),phone=representativePhone.value.trim(),reason=representativeReason.value.trim();if(!name||!position||!email||!reason){showToast({type:"warning",title:"ข้อมูลผู้แทนไม่ครบ",message:"กรุณากรอกชื่อ ตำแหน่ง อีเมล และเหตุผล"});return}c.student.mentor.representative={name,position,email,phone,reason};c.round.mentorConfirmed=true;closeMentorRepresentativeForm();commitAll(false);renderMentorInformation();updateSupervisionStepperStatus();showToast({type:"success",title:"บันทึกผู้แทนพี่เลี้ยงแล้ว",message:name})}
function saveSupervisionResult(draft){const c=getCurrentSupervisionContext();if(!c)return;const summary=supervisionSummary.value.trim();if(!summary){showToast({type:"warning",title:"กรุณากรอกรายละเอียดการนิเทศ",message:"รายละเอียดการนิเทศเป็นข้อมูลหลักที่ต้องมี"});return}Object.assign(c.round,{summary,suggestion:supervisionSuggestion.value.trim(),problem:supervisionProblem.value.trim(),resultStatus:draft?"draft":"complete"});commitAll(false);renderPdfReadiness();updateSupervisionStepperStatus();showToast({type:"success",title:draft?"บันทึกฉบับร่างแล้ว":"บันทึกผลนิเทศแล้ว",message:`${c.student.name} • ครั้งที่ ${c.roundNo}`})}
function readImageFile(f,cb){if(!f)return;const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(f)}function handleSupervisionPhoto(i,f){const c=getCurrentSupervisionContext();if(!c||!f)return;if(!f.type.startsWith("image/")){showToast({type:"error",title:"ไฟล์ไม่ถูกต้อง",message:"กรุณาเลือกไฟล์รูปภาพ"});return}readImageFile(f,url=>{c.round.photos[i]=url;saveTeacherMockState();renderPhotoPreviews();renderPdfReadiness();updateSupervisionStepperStatus();showToast({type:"success",title:`อัปโหลดรูปที่ ${i+1} แล้ว`,message:c.student.name})})}
function renderPhotoPreviews(){const c=getCurrentSupervisionContext();if(!c)return;c.round.photos.forEach((p,i)=>{const el=document.getElementById(`supervisionPhotoPreview${i+1}`);el.innerHTML=p?`<img src="${p}" alt="รูปประกอบการนิเทศ ${i+1}" />`:`<i class="fa-solid fa-image"></i><span>รูปที่ ${i+1}</span>`});supervisionPhotoStatus.textContent=`อัปโหลดแล้ว ${c.round.photos.filter(Boolean).length} / 2 รูป`}
function getPdfReadiness(c){const a=c.student.mentor.representative||c.student.mentor;return[{label:"ชื่อนักศึกษา",ready:!!c.student.name},{label:"ผลการนิเทศ",ready:c.round.resultStatus==="complete"},{label:"รูปภาพประกอบ 2 รูป",ready:!!(c.round.photos[0]&&c.round.photos[1])},{label:"ชื่ออาจารย์นิเทศ",ready:!!teacherCoopState.profile.name},{label:"ชื่อพี่เลี้ยง / ผู้แทน",ready:!!a?.name}]}
function renderPdfReadiness(){const c=getCurrentSupervisionContext();if(!c)return;const a=getPdfReadiness(c),ready=a.every(x=>x.ready);pdfReadinessList.innerHTML=a.map(x=>`<div class="tc-readiness-item ${x.ready?"ready":"missing"}"><i class="fa-solid ${x.ready?"fa-circle-check":"fa-circle-xmark"}"></i><span>${escapeHtml(x.label)}</span></div>`).join("");generatePdfButton.disabled=!ready}
function updateSupervisionStepperStatus(){const c=getCurrentSupervisionContext();if(!c)return;const st={appointment:c.round.appointmentSaved,mentor:c.student.mentor.confirmed||!!c.student.mentor.representative||c.round.mentorConfirmed,result:c.round.resultStatus==="complete",photos:!!(c.round.photos[0]&&c.round.photos[1]),pdf:c.round.pdfGenerated};document.querySelectorAll("[data-supervision-step]").forEach(b=>{const n=b.dataset.supervisionStep;b.classList.toggle("done",!!st[n]);b.classList.toggle("active",teacherCoopState.currentSupervision.step===n)})}
function buildPdfPreviewHtml(){const c=getCurrentSupervisionContext();if(!c)return"";const a=c.student.mentor.representative||c.student.mentor;return`<h1>แบบบันทึกผลการนิเทศสหกิจศึกษา</h1><h2>การนิเทศครั้งที่ ${c.roundNo}</h2><div class="tc-pdf-info"><div><strong>นักศึกษา:</strong> ${escapeHtml(c.student.name)}</div><div><strong>รหัสนักศึกษา:</strong> ${escapeHtml(c.student.id)}</div><div><strong>สาขา:</strong> ${escapeHtml(c.student.major)}</div><div><strong>วันที่นิเทศ:</strong> ${escapeHtml(formatThaiDate(c.round.date))}</div><div><strong>สถานประกอบการ:</strong> ${escapeHtml(c.student.company)}</div><div><strong>ตำแหน่ง:</strong> ${escapeHtml(c.student.position)}</div></div><div class="tc-pdf-section"><h3>รายละเอียดการนิเทศ</h3><p>${escapeHtml(c.round.summary||"-")}</p></div><div class="tc-pdf-section"><h3>ข้อเสนอแนะ</h3><p>${escapeHtml(c.round.suggestion||"-")}</p></div><div class="tc-pdf-section"><h3>ปัญหาที่พบ</h3><p>${escapeHtml(c.round.problem||"-")}</p></div><div class="tc-pdf-section"><h3>รูปภาพประกอบการนิเทศ</h3><div class="tc-pdf-photo-grid"><img src="${c.round.photos[0]}" alt="รูปประกอบ 1" /><img src="${c.round.photos[1]}" alt="รูปประกอบ 2" /></div></div><div class="tc-pdf-signatures"><div class="tc-pdf-signature"><p>ลงชื่อ ............................................................</p><p>(${escapeHtml(teacherCoopState.profile.name)})</p><p>อาจารย์นิเทศ</p></div><div class="tc-pdf-signature"><p>ลงชื่อ ............................................................</p><p>(${escapeHtml(a.name)})</p><p>${c.student.mentor.representative?"ผู้แทนพี่เลี้ยง":"พี่เลี้ยง"}</p></div></div>`}
function previewSupervisionPdf(){const c=getCurrentSupervisionContext();if(!c)return;if(!getPdfReadiness(c).every(x=>x.ready)){showToast({type:"warning",title:"ข้อมูลยังไม่พร้อม",message:"กรุณาทำรายการให้ครบก่อนดูตัวอย่าง PDF"});return}pdfPreviewContent.innerHTML=buildPdfPreviewHtml();openModal("pdfPreviewModal")}
async function generateSupervisionPdf(){const c=getCurrentSupervisionContext();if(!c)return;if(!getPdfReadiness(c).every(x=>x.ready)){showToast({type:"warning",title:"ข้อมูลยังไม่พร้อม",message:"กรุณาทำรายการให้ครบก่อนสร้าง PDF"});return}pdfPreviewContent.innerHTML=buildPdfPreviewHtml();try{if(!window.html2canvas||!window.jspdf?.jsPDF)throw new Error("PDF lib unavailable");const canvas=await window.html2canvas(pdfPreviewContent,{scale:1.7,useCORS:true,backgroundColor:"#fff"}),data=canvas.toDataURL("image/jpeg",.92),{jsPDF}=window.jspdf,pdf=new jsPDF("p","mm","a4"),pw=210,ph=297,iw=pw,ih=canvas.height*iw/canvas.width;let left=ih,pos=0;pdf.addImage(data,"JPEG",0,pos,iw,ih);left-=ph;while(left>0){pos=left-ih;pdf.addPage();pdf.addImage(data,"JPEG",0,pos,iw,ih);left-=ph}pdf.save(`supervision_${c.student.id}_round_${c.roundNo}.pdf`);c.round.pdfGenerated=true;commitAll(false);updateSupervisionStepperStatus();showToast({type:"success",title:"สร้าง PDF เรียบร้อยแล้ว",message:`${c.student.name} • นิเทศครั้งที่ ${c.roundNo}`})}catch(e){console.warn(e);openModal("pdfPreviewModal");showToast({type:"warning",title:"ไม่สามารถสร้างไฟล์โดยตรงได้",message:"เปิดตัวอย่างให้แล้ว สามารถใช้ Print > Save as PDF ได้"})}}

const EVALUATION_CRITERIA={student:[{key:"knowledge",title:"ความรู้ความสามารถ",hint:"ความรู้ที่ใช้ในการทำงาน"},{key:"workQuality",title:"คุณภาพการปฏิบัติงาน",hint:"ความถูกต้องและคุณภาพของผลงาน"},{key:"responsibility",title:"ความรับผิดชอบ",hint:"ตรงต่อเวลาและรับผิดชอบงาน"},{key:"communication",title:"การสื่อสารและทำงานร่วมกัน",hint:"ประสานงานกับทีมได้เหมาะสม"},{key:"problemSolving",title:"การแก้ไขปัญหา",hint:"วิเคราะห์และจัดการปัญหาในการทำงาน"}],company:[{key:"jobSuitability",title:"ความเหมาะสมของงาน",hint:"งานสอดคล้องกับสาขาและทักษะนักศึกษา"},{key:"mentorSupport",title:"การดูแลของพี่เลี้ยง",hint:"ให้คำแนะนำและติดตามนักศึกษา"},{key:"workEnvironment",title:"สภาพแวดล้อมการทำงาน",hint:"ความปลอดภัยและความเหมาะสม"},{key:"learningOpportunity",title:"โอกาสในการเรียนรู้",hint:"เปิดโอกาสให้นักศึกษาพัฒนาทักษะ"},{key:"cooperation",title:"ความร่วมมือกับภาควิชา",hint:"ประสานงานและสนับสนุนการนิเทศ"}],visit2:[{key:"progress",title:"ความก้าวหน้าของงาน",hint:"ความคืบหน้าจากนิเทศครั้งที่ 1"},{key:"knowledge",title:"ความรู้และทักษะ",hint:"นำความรู้มาใช้ในงานจริง"},{key:"adaptation",title:"การปรับตัว",hint:"ปรับตัวกับสภาพแวดล้อมและทีมงาน"},{key:"problemSolving",title:"การแก้ไขปัญหา",hint:"แก้ปัญหาได้อย่างเป็นระบบ"},{key:"professionalism",title:"ความเป็นมืออาชีพ",hint:"ความรับผิดชอบและจริยธรรมการทำงาน"}]};
function renderEvaluations(){renderStudentEvaluationTable();renderCompanyEvaluationTable();renderVisit2EvaluationTable();renderFinalEvaluationGrid()}
function evaluationStatus(e){return e.status==="complete"?'<span class="tc-status tc-status-success">ประเมินแล้ว</span>':e.status==="draft"?'<span class="tc-status tc-status-warning">ฉบับร่าง</span>':'<span class="tc-status tc-status-muted">ยังไม่ประเมิน</span>'}
function renderStudentEvaluationTable(){studentEvaluationBody.innerHTML=getManagedStudents().map(s=>{const e=s.evaluations.student;return`<tr><td><span class="tc-table-primary">${escapeHtml(s.name)}</span><span class="tc-table-secondary">${escapeHtml(s.id)}</span></td><td>${escapeHtml(s.company)}</td><td>${evaluationStatus(e)}</td><td>${e.total??"-"}</td><td><button class="tc-btn tc-btn-primary tc-btn-sm" type="button" onclick="openEvaluation('${escapeHtml(s.id)}','student')">${e.status==="complete"?"ดู / แก้ไข":"ประเมิน"}</button></td></tr>`}).join("");refreshResponsiveTableLabels()}
function renderCompanyEvaluationTable(){companyEvaluationBody.innerHTML=getManagedStudents().map(s=>{const e=s.evaluations.company;return`<tr><td><span class="tc-table-primary">${escapeHtml(s.name)}</span><span class="tc-table-secondary">${escapeHtml(s.id)}</span></td><td>${escapeHtml(s.company)}</td><td>${evaluationStatus(e)}</td><td>${e.total??"-"}</td><td><button class="tc-btn tc-btn-primary tc-btn-sm" type="button" onclick="openEvaluation('${escapeHtml(s.id)}','company')">${e.status==="complete"?"ดู / แก้ไข":"ประเมิน"}</button></td></tr>`}).join("");refreshResponsiveTableLabels()}
function renderVisit2EvaluationTable(){visit2EvaluationBody.innerHTML=getManagedStudents().map(s=>{const e=s.evaluations.visit2,r=s.supervision[2];return`<tr><td><span class="tc-table-primary">${escapeHtml(s.name)}</span><span class="tc-table-secondary">${escapeHtml(s.id)}</span></td><td>${r.appointmentSaved?escapeHtml(formatThaiDate(r.date)):"-"}</td><td>${r.resultStatus==="complete"?'<span class="tc-status tc-status-success">บันทึกผลแล้ว</span>':'<span class="tc-status tc-status-warning">ยังไม่เสร็จ</span>'}</td><td>${evaluationStatus(e)}</td><td><button class="tc-btn tc-btn-primary tc-btn-sm" type="button" ${r.resultStatus!=="complete"?"disabled":""} onclick="openEvaluation('${escapeHtml(s.id)}','visit2')">${e.status==="complete"?"ดู / แก้ไข":"ประเมิน"}</button></td></tr>`}).join("");refreshResponsiveTableLabels()}
function openEvaluation(id,type){const s=findStudent(id);if(!s||!EVALUATION_CRITERIA[type])return;teacherCoopState.currentEvaluation={studentId:id,type};const titles={student:"ประเมินนักศึกษาสหกิจ",company:"ประเมินสถานประกอบการ",visit2:"ประเมินนักศึกษาจากการนิเทศครั้งที่ 2"};evaluationModalTitle.textContent=titles[type];evaluationStudentPreview.innerHTML=`<strong>${escapeHtml(s.name)}</strong><span>${escapeHtml(s.id)} • ${escapeHtml(s.company)}</span>`;const e=s.evaluations[type];evaluationCriteriaContainer.innerHTML=`<div class="tc-evaluation-criteria">${EVALUATION_CRITERIA[type].map(c=>`<div class="tc-criterion"><div><strong>${escapeHtml(c.title)}</strong><span>${escapeHtml(c.hint)}</span></div><input type="number" min="1" max="5" step="1" class="evaluation-score-input" data-key="${escapeHtml(c.key)}" value="${escapeHtml(e.scores[c.key]??"")}" placeholder="1-5" /></div>`).join("")}</div>`;evaluationComment.value=e.comment||"";openModal("evaluationModal")}
function collectEvaluationForm(){const scores={};document.querySelectorAll(".evaluation-score-input").forEach(i=>{const v=Number(i.value);if(!Number.isNaN(v)&&v>=1&&v<=5)scores[i.dataset.key]=v});return{scores,comment:evaluationComment.value.trim()}}
function saveEvaluation(draft){const{studentId,type}=teacherCoopState.currentEvaluation,s=findStudent(studentId);if(!s||!type)return;const f=collectEvaluationForm(),criteria=EVALUATION_CRITERIA[type];if(!draft&&Object.keys(f.scores).length!==criteria.length){showToast({type:"warning",title:"กรอกคะแนนไม่ครบ",message:"กรุณาให้คะแนนทุกหัวข้อก่อนส่งผลประเมิน"});return}const vals=Object.values(f.scores),e=s.evaluations[type];e.scores=f.scores;e.comment=f.comment;e.status=draft?"draft":"complete";e.total=vals.length?Number((vals.reduce((a,b)=>a+b,0)/(vals.length*5)*100).toFixed(1)):null;closeModal("evaluationModal");commitAll();showToast({type:"success",title:draft?"บันทึกฉบับร่างแล้ว":"ส่งผลประเมินแล้ว",message:s.name})}
function renderFinalEvaluationGrid(){const a=getManagedStudents();finalEvaluationGrid.innerHTML=a.length?a.map(s=>{const done=FINAL_WORK_TYPES.filter(({key})=>s.evaluations.final[key].score!==null).length;return`<div class="tc-final-student-card"><div class="tc-final-student-header"><div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.id)} • ${escapeHtml(s.company)}</p></div><div class="tc-final-progress"><strong>${done} / ${FINAL_WORK_TYPES.length}</strong><span>${done===FINAL_WORK_TYPES.length?"ประเมินครบแล้ว":"ความคืบหน้า"}</span></div></div><div class="tc-final-items">${FINAL_WORK_TYPES.map(({key,label})=>{const i=s.evaluations.final[key];return`<div class="tc-final-item"><strong>${escapeHtml(label)}</strong><span>${i.score===null?"ยังไม่ประเมิน":`คะแนน ${i.score}/100`}</span><button class="tc-btn ${i.score===null?"tc-btn-primary":"tc-btn-outline"} tc-btn-sm" type="button" onclick="openFinalWorkEvaluation('${escapeHtml(s.id)}','${escapeHtml(key)}')">${i.score===null?"ประเมิน":"ดู / แก้ไข"}</button></div>`}).join("")}</div></div>`}).join(""):`<div class="tc-empty show"><i class="fa-solid fa-book-open"></i><strong>ยังไม่มีนักศึกษาสำหรับประเมินผลงาน</strong></div>`}
function openFinalWorkEvaluation(id,type){const s=findStudent(id),cfg=FINAL_WORK_TYPES.find(x=>x.key===type);if(!s||!cfg)return;teacherCoopState.currentFinalWork={studentId:id,type};const i=s.evaluations.final[type];finalWorkModalTitle.textContent=`ประเมิน${cfg.label}`;finalWorkStudentPreview.innerHTML=`<strong>${escapeHtml(s.name)}</strong><span>${escapeHtml(s.id)} • ${escapeHtml(s.company)}</span>`;finalWorkScore.value=i.score??"";finalWorkComment.value=i.comment||"";openModal("finalWorkModal")}
function saveFinalWorkEvaluation(){const{studentId,type}=teacherCoopState.currentFinalWork,s=findStudent(studentId);if(!s||!type)return;const score=Number(finalWorkScore.value),comment=finalWorkComment.value.trim();if(Number.isNaN(score)||score<0||score>100){showToast({type:"warning",title:"คะแนนไม่ถูกต้อง",message:"กรุณากรอกคะแนนระหว่าง 0 ถึง 100"});return}s.evaluations.final[type].score=score;s.evaluations.final[type].comment=comment;closeModal("finalWorkModal");commitAll();showToast({type:"success",title:"บันทึกผลประเมินแล้ว",message:s.name})}

function loadTeacherProfile(){const u=JSON.parse(localStorage.getItem("currentUser")||"null");if(u){teacherCoopState.profile.name=u.name||teacherCoopState.profile.name;teacherCoopState.profile.email=u.email||teacherCoopState.profile.email}const p=teacherCoopState.profile;profileName.value=p.name;profileEmail.value=p.email;profileMajor.value=p.major;profilePassword.value="";profileConfirmPassword.value="";headerUserName.textContent=p.name;overviewGreeting.textContent=`ยินดีต้อนรับ, ${p.name}`;profileSummaryName.textContent=p.name;profileSummaryEmail.textContent=p.email;profileSummaryMajor.textContent=p.major;const clean=p.name.replace(/^(ผศ\.ดร\.|รศ\.ดร\.|ศ\.ดร\.|ดร\.|ผศ\.|รศ\.|ศ\.)/u,"").trim();profileAvatar.textContent=clean.charAt(0)||"อ"}
function submitTeacherProfile(e){e.preventDefault();const name=profileName.value.trim(),email=profileEmail.value.trim(),pw=profilePassword.value,cpw=profileConfirmPassword.value;if(!name||!email){showToast({type:"warning",title:"กรอกข้อมูลไม่ครบ",message:"กรุณากรอกชื่อและอีเมล"});return}if(pw&&pw.length<6){showToast({type:"warning",title:"รหัสผ่านสั้นเกินไป",message:"รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร"});return}if(pw!==cpw){showToast({type:"error",title:"รหัสผ่านไม่ตรงกัน",message:"รหัสผ่านใหม่และยืนยันรหัสผ่านต้องตรงกัน"});return}teacherCoopState.profile.name=name;teacherCoopState.profile.email=email;const u=JSON.parse(localStorage.getItem("currentUser")||"{}");localStorage.setItem("currentUser",JSON.stringify({...u,name,email}));saveTeacherMockState();loadTeacherProfile();showToast({type:"success",title:"บันทึกข้อมูลส่วนตัวแล้ว",message:pw?"ข้อมูลส่วนตัวและรหัสผ่านถูกบันทึกใน Mockup":"ข้อมูลส่วนตัวถูกอัปเดตเรียบร้อยแล้ว"})}

function openModal(id){const m=document.getElementById(id);if(!m)return;m.classList.add("show");m.setAttribute("aria-hidden","false");document.body.style.overflow="hidden"}function closeModal(id){const m=document.getElementById(id);if(!m)return;m.classList.remove("show");m.setAttribute("aria-hidden","true");if(!document.querySelector(".tc-modal.show"))document.body.style.overflow=""}
function showConfirm({title="ยืนยันการดำเนินการ",message="",confirmText="ยืนยัน",tone="primary"}={}){return new Promise(resolve=>{confirmTitle.textContent=title;confirmMessage.textContent=message;confirmOkButton.textContent=confirmText;confirmOkButton.className=tone==="danger"?"tc-btn tc-btn-danger":"tc-btn tc-btn-primary";confirmIcon.innerHTML=tone==="danger"?'<i class="fa-solid fa-triangle-exclamation"></i>':'<i class="fa-solid fa-circle-question"></i>';const done=r=>{confirmOkButton.onclick=null;confirmCancelButton.onclick=null;closeModal("confirmModal");resolve(r)};confirmOkButton.onclick=()=>done(true);confirmCancelButton.onclick=()=>done(false);openModal("confirmModal")})}
function showToast({type="success",title="สำเร็จ",message="",duration=3200}={}){const icons={success:"fa-circle-check",error:"fa-circle-xmark",warning:"fa-triangle-exclamation",info:"fa-circle-info"},t=document.createElement("div");t.className=`tc-toast ${type}`;t.innerHTML=`<div class="tc-toast-icon"><i class="fa-solid ${icons[type]||icons.info}"></i></div><div><strong>${escapeHtml(title)}</strong>${message?`<span>${escapeHtml(message)}</span>`:""}</div><button type="button"><i class="fa-solid fa-xmark"></i></button>`;const rm=()=>t.remove();t.querySelector("button").addEventListener("click",rm);toastContainer.appendChild(t);setTimeout(rm,duration)}
function commitAll(){saveTeacherMockState();updateOverview();renderStudentSearch();renderManagedStudents();renderStudentConfirmations();renderRequests();renderSupervision();renderEvaluations();refreshResponsiveTableLabels()}
async function teacherLogout(){if(!await showConfirm({title:"ออกจากระบบ",message:"ต้องการออกจากระบบหรือไม่?",confirmText:"ออกจากระบบ",tone:"danger"}))return;localStorage.removeItem("currentUser");if(typeof window.logout==="function"){window.logout();return}window.location.href="login.html"}

function bindTeacherEvents(){document.querySelectorAll(".tc-sidebar-item[data-panel]").forEach(b=>b.addEventListener("click",()=>switchTeacherPanel(b.dataset.panel)));document.querySelectorAll("[data-student-tab]").forEach(b=>b.addEventListener("click",()=>switchStudentTab(b.dataset.studentTab)));document.querySelectorAll("[data-request-filter]").forEach(b=>b.addEventListener("click",()=>setRequestFilter(b.dataset.requestFilter)));document.querySelectorAll("[data-supervision-tab]").forEach(b=>b.addEventListener("click",()=>switchSupervisionTab(b.dataset.supervisionTab)));document.querySelectorAll("[data-evaluation-tab]").forEach(b=>b.addEventListener("click",()=>switchEvaluationTab(b.dataset.evaluationTab)));document.querySelectorAll("[data-supervision-step]").forEach(b=>b.addEventListener("click",()=>switchSupervisionStep(b.dataset.supervisionStep)));["studentSearchInput","studentMajorFilter","studentCareFilter"].forEach(id=>{document.getElementById(id)?.addEventListener("input",renderStudentSearch);document.getElementById(id)?.addEventListener("change",renderStudentSearch)});["requestSearchInput","requestMajorFilter"].forEach(id=>{document.getElementById(id)?.addEventListener("input",renderRequests);document.getElementById(id)?.addEventListener("change",renderRequests)});["supervisionSearchInput","supervisionStatusFilter"].forEach(id=>{document.getElementById(id)?.addEventListener("input",renderSupervisionOverview);document.getElementById(id)?.addEventListener("change",renderSupervisionOverview)});supervisionPhoto1?.addEventListener("change",e=>{handleSupervisionPhoto(0,e.target.files?.[0]);e.target.value=""});supervisionPhoto2?.addEventListener("change",e=>{handleSupervisionPhoto(1,e.target.files?.[0]);e.target.value=""});profileForm?.addEventListener("submit",submitTeacherProfile);evaluationForm?.addEventListener("submit",e=>{e.preventDefault();saveEvaluation(false)});document.querySelectorAll("[data-close-modal]").forEach(b=>b.addEventListener("click",()=>{const m=b.closest(".tc-modal");if(m)closeModal(m.id)}));document.querySelectorAll(".tc-modal").forEach(m=>m.addEventListener("mousedown",e=>{if(e.target===m&&m.id!=="confirmModal")closeModal(m.id)}));document.addEventListener("keydown",e=>{if(e.key!=="Escape")return;const m=[...document.querySelectorAll(".tc-modal.show")].at(-1);if(m&&m.id!=="confirmModal")closeModal(m.id)});window.addEventListener("resize",refreshResponsiveTableLabels)}
document.addEventListener("DOMContentLoaded",()=>{loadTeacherMockState();bindTeacherEvents();loadTeacherProfile();commitAll()});
